# Program will take a CSV generated by Sam's audio preporcessing output, group by song ID
# and split 80/10/10 into training, testing, validation

# Justification: I chose an 80/10/10 split to have maximum training data to begin our models with
# This can be revisited in the future

# Citation
# Claude assisted a series of inquiries relating to the use of pandas and documentation for tasks related to 
# the CSV library. I had previously used manual CSV processing and used the AI to help me identify important methods
# I would need.

# imports
import csv
import pandas as pd
from sklearn.model_selection import train_test_split
from pathlib import Path

# load input CSV
input_csv = Path(__file__).parent.parent / "Data" / "gtzan_57_features.csv"

# output path
output_path = Path(__file__).parent.parent / "Data" / "gtzan_57_features_split.csv"

# create a random seed
random_seed = 46

# control ratios
train_ratio = 0.8
test_ratio = 0.1
val_ratio = 0.1

# load in CSV
df = pd.read_csv(input_csv)

# begin formatting the data frame
# group by song ID
group_df = df.groupby("song_id")

# keep one genre label per song ID
group_df = group_df.agg(label=("label", "first"))
group_df = group_df.reset_index()

# split into the three sets
# create test set
train_songs, test_songs = train_test_split(
    group_df,
    test_size=test_ratio,
    random_state=random_seed,
    stratify=group_df["label"],
)

# create validation set
train_songs, val_songs = train_test_split(
    train_songs,
    test_size=val_ratio / (train_ratio + val_ratio),
    random_state=random_seed,
    stratify=train_songs["label"],
)

# add in the new split column
train_songs["split"] = "train"
test_songs["split"] = "test"
val_songs["split"] = "val"

# combine the three
combined_df = pd.concat([train_songs, test_songs, val_songs])

# merge to apply split col to original df based on song
final_df = pd.merge(df, combined_df[["song_id", "split"]], on="song_id", how="left")

# save
final_df.to_csv(output_path, index=False)

